import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 44 Patterns of culture","description":"学习 限制性与非限制性从句的范围差异，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 44 Patterns of culture","description":"学习 限制性与非限制性从句的范围差异，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 限制性与非限制性从句的范围差异，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 43 Are there strangers in space?","link":"/life/english/new-concept/book-4/unit-06/lesson-043"},"next":{"text":"第四册：流利英语 · Lesson 45 Of men and galaxies","link":"/life/english/new-concept/book-4/unit-06/lesson-045"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 43 Are there strangers in space?","link":"/life/english/new-concept/book-4/unit-06/lesson-043"},"next":{"text":"第四册：流利英语 · Lesson 45 Of men and galaxies","link":"/life/english/new-concept/book-4/unit-06/lesson-045"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-06/lesson-044.md","filePath":"life/english/new-concept/book-4/unit-06/lesson-044.md"}'),i={name:"life/english/new-concept/book-4/unit-06/lesson-044.md"};function r(s,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-44-patterns-of-culture" tabindex="-1">第四册：流利英语 · Lesson 44 Patterns of culture <a class="header-anchor" href="#第四册-流利英语-·-lesson-44-patterns-of-culture" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 44 Patterns of culture&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元 6</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>通过文化模式阅读训练相对化描述，避免将一种社会中的常见行为说成每个成员都遵守的本质。区分作者观察的年代、地点和样本，注意译词可能带入评价。重点使用范围限定和非限制性从句，既说明背景，又不把补充评论误写成排他性的分类。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>custom</td><td>/ˈkʌstəm/</td><td>n.</td><td>习俗</td><td>a local custom</td></tr><tr><td>norm</td><td>/nɔːm/</td><td>n.</td><td>规范</td><td>a social norm</td></tr><tr><td>context</td><td>/ˈkɒntekst/</td><td>n.</td><td>语境</td><td>cultural context</td></tr><tr><td>diversity</td><td>/daɪˈvɜːsəti/</td><td>n.</td><td>多样性</td><td>internal diversity</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>within a community — 在某个社群内部</li><li>from one context to another — 从一种情境到另一种情境</li></ul><h2 id="语法讲解-限制性与非限制性从句的范围差异" tabindex="-1">语法讲解：限制性与非限制性从句的范围差异 <a class="header-anchor" href="#语法讲解-限制性与非限制性从句的范围差异" aria-label="Permalink to &quot;语法讲解：限制性与非限制性从句的范围差异&quot;">​</a></h2><p>The participants who arrived early helped us. 只说早到的那部分参与者；The participants, who arrived early, helped us. 把早到作为这组参与者共同的补充信息。逗号改变所指范围，不只是朗读停顿。非限制性从句通常不用 that，也不能省关系代词。文化描述尤其要先限定群体，再加补充说明；否则容易把少数人的观察扩展成整个文化的属性。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The visitors who had attended the workshop recognised the greeting.</p></blockquote><p>参加过工作坊的那些访客认出了这种问候方式。</p><p>who…workshop 是限制性从句，只选出访客中的一部分；没有宣称全部访客参加过。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>给 who 从句随意加逗号会改变范围：有逗号时通常将参加工作坊作为整组访客的补充信息。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>分别朗读有逗号和无逗号的 who 从句；用停顿差异提示补充信息，同时口头说明两句范围不同。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The participants who had joined earlier sessions recognised the greeting. Others asked about its meaning. Our guide reminded us that practices can vary within the same community.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句跨文化活动观察，明确样本并保留社群内部差异。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>用限制性从句划分观察对象，再说明内部多样性，避免绝对文化标签。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例是否说所有访客都参加了工作坊？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> 限制性从句只限定其中一组。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：Our guide, ___ grew up locally, explained the custom.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> who</p><p><strong>解析：</strong> 指人且为非限制性从句，使用 who。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>非限制性从句可否用 that 替代 who？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 通常不可以。</p><p><strong>解析：</strong> 标准书面语的非限制性从句不用 that。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：限制性与非限制性从句的范围差异。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-043">上一课</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-06/lesson-045">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",r]]);export{u as __pageData,b as default};
